const j = $json || {};
const execution = j.execution || {};
const workflow = j.workflow || {};
// n8n Error Trigger nests the real error under execution.error (the old code read $json.error -> always {}).
const error = execution.error || j.error || {};
const workflowName = workflow.name || workflow.id || 'unknown';
const executionId = execution.id || 'unknown';
const lastNode = execution.lastNodeExecuted || (error.node && error.node.name) || 'unknown';
const httpCode = error.httpCode || error.statusCode || (error.context && error.context.httpCode) || '';
let message = error.message || error.description || '';
if (!message && error.cause) { message = error.cause.message || ''; }
if (!message) { message = (error && Object.keys(error).length) ? JSON.stringify(error) : '(无错误详情)'; }
const ts = new Date(Date.now() + 8*3600*1000).toISOString().replace('T',' ').slice(0,16);
const stack = (error.stack || '').split('\n').slice(0, 4).join('\n');
let md = `### 🔴 工作流失败 · ${workflowName}\n\n`;
md += `- 时间: ${ts}\n`;
md += `- 执行: ${executionId}\n`;
md += `- 失败节点: ${lastNode}\n`;
md += `- 错误: ${httpCode ? '[HTTP ' + httpCode + '] ' : ''}${message}\n`;
if (stack) { md += `\n\`\`\`\n${stack}\n\`\`\`\n`; }
return [{ json: { markdown: md, severity: 'error', source: workflowName } }];
